+    private int recordCount(FileChannel channel) {
+        try {
+            return (int) (channel.position() / ABORTED_TXN_RECORD_SIZE);
+        } catch (IOException e) {
+            throw new KafkaException("Failed read position from the transaction index " + file.getAbsolutePath(), e);
