+    public void testLastStableOffsetDoesNotRegressWhenTransactionsCompleteOutOfOrder() {
+        appendClientEntry(stateManager, 1L, epoch, 0, 0L, true);
+        appendClientEntry(stateManager, 2L, epoch, 0, 10L, true);
